arguments.command:
python3 << 'EOF'
import parse

fmt = '''
            letters: {:w}
            non-letters: {:W}
            whitespace: "{:s}"
            non-whitespace: \t{:S}\n
            digits: {:d}
            non-digits: {:D}
            numbers with thousands: {:n}
            fixed-point: {:f}
            floating-point: {:e}
            general numbers: {:g} {:g}
            binary: {:b}
            octal: {:o}
            hex: {:x}
'''

text = '''
            letters: abcdef_GHIJLK
            non-letters: !@#%$ *^%
            whitespace: "   \t\n"
            non-whitespace: \tabc\n
            digits: 0xabcdef
            non-digits: abcdef
            numbers with thousands: 1.000.000
            fixed-point: 0.00001
            floating-point: NAN
            general numbers: 1.1e10 nan
            binary: 0B1000
            octal: 0O1000
            hex: 0X1000
'''

p = parse.Parser(fmt)
print('Expression:')
print(repr(p._expression[:500]))
print()
m = p._search_re.search(text)
print('Match:', m is not None)
if m:
    print('Number of groups:', len(m.groups()))
    for i in range(len(m.groups()) + 2):
        try:
            val = m.group(i)
            print(f'Group {i}: {val!r}')
        except IndexError:
            print(f'Group {i}: IndexError')
EOF
